∀ {S : @AddSubmonoid Nat (@AddMonoid.toAddZeroClass Nat Nat.instAddMonoid)} {m e : Nat} {value : Fin e → Nat}
  {injective_value : @Function.Injective (Fin e) Nat value} {value_min : ∀ (i : Fin e), NSP14.IsAperyMin S m (value i)}
  {pair_min :
    ∀ (i j : Fin e), NSP14.IsAperyMin S m (@HAdd.hAdd Nat Nat Nat (@instHAdd Nat instAddNat) (value i) (value j))}
  {pair_unique :
    ∀ (i j k l : Fin e),
      @Eq Nat (@HAdd.hAdd Nat Nat Nat (@instHAdd Nat instAddNat) (value i) (value j))
          (@HAdd.hAdd Nat Nat Nat (@instHAdd Nat instAddNat) (value k) (value l)) →
        Or (And (@Eq (Fin e) i k) (@Eq (Fin e) j l)) (And (@Eq (Fin e) i l) (@Eq (Fin e) j k))}
  {value_1 : Fin e → Nat} {injective_value_1 : @Function.Injective (Fin e) Nat value_1}
  {value_min_1 : ∀ (i : Fin e), NSP14.IsAperyMin S m (value_1 i)}
  {pair_min_1 :
    ∀ (i j : Fin e), NSP14.IsAperyMin S m (@HAdd.hAdd Nat Nat Nat (@instHAdd Nat instAddNat) (value_1 i) (value_1 j))}
  {pair_unique_1 :
    ∀ (i j k l : Fin e),
      @Eq Nat (@HAdd.hAdd Nat Nat Nat (@instHAdd Nat instAddNat) (value_1 i) (value_1 j))
          (@HAdd.hAdd Nat Nat Nat (@instHAdd Nat instAddNat) (value_1 k) (value_1 l)) →
        Or (And (@Eq (Fin e) i k) (@Eq (Fin e) j l)) (And (@Eq (Fin e) i l) (@Eq (Fin e) j k))},
  @Eq (NSP14.AperyPairData S m e) (@NSP14.AperyPairData.mk S m e value injective_value value_min pair_min pair_unique)
      (@NSP14.AperyPairData.mk S m e value_1 injective_value_1 value_min_1 pair_min_1 pair_unique_1) →
    @Eq (Fin e → Nat) value value_1

type:
∀ {S : AddSubmonoid ℕ} {m e : ℕ} {value : Fin e → ℕ} {injective_value : Function.Injective value}
  {value_min : ∀ (i : Fin e), NSP14.IsAperyMin S m (value i)}
  {pair_min : ∀ (i j : Fin e), NSP14.IsAperyMin S m (value i + value j)}
  {pair_unique : ∀ (i j k l : Fin e), value i + value j = value k + value l → i = k ∧ j = l ∨ i = l ∧ j = k}
  {value_1 : Fin e → ℕ} {injective_value_1 : Function.Injective value_1}
  {value_min_1 : ∀ (i : Fin e), NSP14.IsAperyMin S m (value_1 i)}
  {pair_min_1 : ∀ (i j : Fin e), NSP14.IsAperyMin S m (value_1 i + value_1 j)}
  {pair_unique_1 : ∀ (i j k l : Fin e), value_1 i + value_1 j = value_1 k + value_1 l → i = k ∧ j = l ∨ i = l ∧ j = k},
  { value := value, injective_value := injective_value, value_min := value_min, pair_min := pair_min,
        pair_unique := pair_unique } =
      { value := value_1, injective_value := injective_value_1, value_min := value_min_1, pair_min := pair_min_1,
        pair_unique := pair_unique_1 } →
    value = value_1

