type:
∀ {k : Type u} {inst : Field k} {σ : Type u} {M : ModuleCat (NSP14.Homological.VariableRing k σ)}
  {piece : ℤ → ModuleCat k} {inclusion : (q : ℤ) → ↑(piece q) →ₗ[k] ↑(NSP14.Homological.coefficientModule k σ M)}
  {sum_bijective :
    Function.Bijective ⇑(DirectSum.toModule k ℤ (↑(NSP14.Homological.coefficientModule k σ M)) inclusion)}
  {variableMap : σ → (q : ℤ) → ↑(piece q) →ₗ[k] ↑(piece (q + 1))}
  {variable_commutes :
    ∀ (_x : σ) (q : ℤ) (a : ↑(piece q)),
      (inclusion (q + 1)) ((variableMap _x q) a) = MvPolynomial.X _x • (inclusion q) a}
  {piece_1 : ℤ → ModuleCat k} {inclusion_1 : (q : ℤ) → ↑(piece_1 q) →ₗ[k] ↑(NSP14.Homological.coefficientModule k σ M)}
  {sum_bijective_1 :
    Function.Bijective ⇑(DirectSum.toModule k ℤ (↑(NSP14.Homological.coefficientModule k σ M)) inclusion_1)}
  {variableMap_1 : σ → (q : ℤ) → ↑(piece_1 q) →ₗ[k] ↑(piece_1 (q + 1))}
  {variable_commutes_1 :
    ∀ (_x : σ) (q : ℤ) (a : ↑(piece_1 q)),
      (inclusion_1 (q + 1)) ((variableMap_1 _x q) a) = MvPolynomial.X _x • (inclusion_1 q) a},
  { piece := piece, inclusion := inclusion, sum_bijective := sum_bijective, variableMap := variableMap,
        variable_commutes := variable_commutes } =
      { piece := piece_1, inclusion := inclusion_1, sum_bijective := sum_bijective_1, variableMap := variableMap_1,
        variable_commutes := variable_commutes_1 } →
    piece = piece_1 ∧ inclusion ≍ inclusion_1 ∧ variableMap ≍ variableMap_1

