∀ {k : Type u} [inst : Field k] {σ : Type u} {M : ModuleCat (NSP14.Homological.VariableRing k σ)}
  (self : NSP14.Homological.GradedPolynomialModule k σ M) (_x : σ) (q : ℤ) (a : ↑(self.piece q)),
  (self.inclusion (q + 1)) ((self.variableMap _x q) a) = MvPolynomial.X _x • (self.inclusion q) a

