∀ {k L σ : Type u} [inst : Field k] [inst_1 : Field L] [inst_2 : Algebra k L]
  {M : ModuleCat (NSP14.Homological.VariableRing k σ)} {N : ModuleCat (NSP14.Homological.VariableRing L σ)}
  {G : NSP14.Homological.GradedPolynomialModule k σ M} {H : NSP14.Homological.GradedPolynomialModule L σ N}
  {e : NSP14.Homological.polynomialBaseChangeModule k L σ M ≅ N}
  (self : NSP14.Homological.GradedScalarComparison k L σ G H e) (q : ℤ) (a : ↑(G.piece q)),
  (H.inclusion q) ((self.pieceIso q) (1 ⊗ₜ[k] a)) =
    (CategoryTheory.ConcreteCategory.hom e.hom) (1 ⊗ₜ[k] (G.inclusion q) a)

∀ {k L σ : Type u} {inst : Field k} {inst_1 : Field L} {inst_2 : Algebra k L}
  {M : ModuleCat (NSP14.Homological.VariableRing k σ)} {N : ModuleCat (NSP14.Homological.VariableRing L σ)}
  {G : NSP14.Homological.GradedPolynomialModule k σ M} {H : NSP14.Homological.GradedPolynomialModule L σ N}
  {e : NSP14.Homological.polynomialBaseChangeModule k L σ M ≅ N}
  {pieceIso : (q : ℤ) → TensorProduct k L ↑(G.piece q) ≃ₗ[L] ↑(H.piece q)}
  {inclusion_commutes :
    ∀ (q : ℤ) (a : ↑(G.piece q)),
      (H.inclusion q) ((pieceIso q) (1 ⊗ₜ[k] a)) =
        (CategoryTheory.ConcreteCategory.hom e.hom) (1 ⊗ₜ[k] (G.inclusion q) a)}
  {pieceIso_1 : (q : ℤ) → TensorProduct k L ↑(G.piece q) ≃ₗ[L] ↑(H.piece q)}
  {inclusion_commutes_1 :
    ∀ (q : ℤ) (a : ↑(G.piece q)),
      (H.inclusion q) ((pieceIso_1 q) (1 ⊗ₜ[k] a)) =
        (CategoryTheory.ConcreteCategory.hom e.hom) (1 ⊗ₜ[k] (G.inclusion q) a)},
  { pieceIso := pieceIso, inclusion_commutes := inclusion_commutes } =
