  {Z Q : ℕ → ModuleCat (NSP14.Homological.VariableRing k σ)} {rank : ℕ → ℕ}
  {basis : (i : ℕ) → Module.Basis (ULift.{u, 0} (Fin (rank i))) (NSP14.Homological.VariableRing k σ) ↑(Q i)}
  {start : Z 0 ≅ M} {inc : (i : ℕ) → Z (i + 1) ⟶ Q i} {cover : (i : ℕ) → Q i ⟶ Z i}
  {zero : ∀ (i : ℕ), CategoryTheory.CategoryStruct.comp (inc i) (cover i) = 0}
